"""
NexusBot Admin Panel — HTML Templates (embedded for zero-folder deployment).
Served via Jinja2 DictLoader in main.py.
"""

TEMPLATES = {
    "admin/admins.html": "{% extends \"admin/base.html\" %}\n{% block title %}Manage Admins — NexusBot Admin{% endblock %}\n{% block page_title %}Manage Admins{% endblock %}\n{% block breadcrumb %}Admins{% endblock %}\n\n{% block content %}\n<div class=\"grid-2\" style=\"gap:24px; align-items:start;\">\n    <div class=\"card\">\n        <div class=\"card-header\">➕ Add Sub Admin</div>\n        <form method=\"POST\" action=\"/admin/admins/add\">\n            <div class=\"form-group\">\n                <label class=\"form-label\">TELEGRAM ID *</label>\n                <input type=\"text\" name=\"telegram_id\" class=\"form-control\" required\n                    placeholder=\"User's Telegram numeric ID\">\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">NAME</label>\n                <input type=\"text\" name=\"name\" class=\"form-control\"\n                    placeholder=\"Display name\">\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">USERNAME *</label>\n                <input type=\"text\" name=\"username\" class=\"form-control\" required\n                    placeholder=\"Login username for admin panel\">\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">PASSWORD *</label>\n                <input type=\"password\" name=\"password\" class=\"form-control\" required\n                    placeholder=\"Login password\">\n            </div>\n            <button type=\"submit\" class=\"btn btn-primary\">✅ Add Sub Admin</button>\n        </form>\n    </div>\n\n    <div class=\"card\">\n        <div class=\"card-header\">👥 Current Sub Admins</div>\n        {% if sub_admins %}\n        <div class=\"table-wrap\">\n            <table>\n                <thead>\n                    <tr>\n                        <th>ID</th>\n                        <th>Name</th>\n                        <th>Username</th>\n                        <th>Action</th>\n                    </tr>\n                </thead>\n                <tbody>\n                {% for a in sub_admins %}\n                <tr>\n                    <td style=\"color:var(--text3);\">{{ a.telegram_id }}</td>\n                    <td>{{ a.name }}</td>\n                    <td>@{{ a.username }}</td>\n                    <td>\n                        <form method=\"POST\" action=\"/admin/admins/remove/{{ a.telegram_id }}\"\n                            onsubmit=\"return confirm('Remove this sub-admin?')\">\n                            <button class=\"btn btn-danger btn-sm\">🗑️ Remove</button>\n                        </form>\n                    </td>\n                </tr>\n                {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        {% else %}\n        <div style=\"text-align:center; padding:30px; color:var(--text3);\">\n            No sub-admins appointed yet.\n        </div>\n        {% endif %}\n    </div>\n</div>\n{% endblock %}\n",
    "admin/apk.html": "{% extends \"admin/base.html\" %}\n{% block title %}APK Manager — NexusBot Admin{% endblock %}\n{% block page_title %}APK Manager{% endblock %}\n{% block breadcrumb %}APK Manager{% endblock %}\n\n{% block content %}\n<div class=\"grid-2\" style=\"gap:24px; align-items:start;\">\n    <!-- Upload / Replace APK -->\n    <div class=\"card\">\n        <div class=\"card-header\">📱 Upload / Replace APK</div>\n        <div style=\"padding:14px; background:rgba(124,58,237,0.08); border:1px solid rgba(124,58,237,0.2); border-radius:12px; margin-bottom:20px; font-size:13px; color:var(--text2);\">\n            ℹ️ Uploading a new APK will <strong>archive</strong> the current one. Users will silently receive the new APK on next download. <strong>No auto-notification</strong> — use Broadcast to inform users.\n        </div>\n        <form method=\"POST\" action=\"/admin/apk/replace\">\n            <div class=\"form-group\">\n                <label class=\"form-label\">TELEGRAM FILE ID *</label>\n                <input type=\"text\" name=\"file_id\" class=\"form-control\" required\n                    placeholder=\"e.g. BQACAgIAAxkBAAIB...\">\n                <div style=\"margin-top:6px; font-size:11px; color:var(--text3);\">\n                    Send APK to your bot → Forward to @userinfobot → Copy file_id\n                </div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">FILE NAME</label>\n                <input type=\"text\" name=\"file_name\" class=\"form-control\" value=\"App.apk\"\n                    placeholder=\"MyApp.apk\">\n            </div>\n            <div class=\"grid-2\" style=\"gap:12px;\">\n                <div class=\"form-group\">\n                    <label class=\"form-label\">VERSION</label>\n                    <input type=\"text\" name=\"version\" class=\"form-control\"\n                        value=\"{{ (active_apk.version | float + 0.1) | round(1) if active_apk else '1.0' }}\"\n                        placeholder=\"1.0.0\">\n                </div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">CHANGELOG / WHAT'S NEW</label>\n                <textarea name=\"changelog\" class=\"form-control\" rows=\"4\"\n                    placeholder=\"- Bug fixes and performance improvements&#10;- New features added...\"></textarea>\n            </div>\n            <button type=\"submit\" class=\"btn btn-primary\" style=\"width:100%;\"\n                onclick=\"return confirm('Replace active APK? Old one will be archived.')\">\n                🔄 Replace APK (Archive Old)\n            </button>\n        </form>\n    </div>\n\n    <!-- APK Status -->\n    <div style=\"display:flex; flex-direction:column; gap:16px;\">\n        <!-- Active APK -->\n        <div class=\"card\">\n            <div class=\"card-header\">✅ Currently Active APK</div>\n            {% if active_apk %}\n            <div style=\"padding:16px; background:var(--bg3); border-radius:12px; border:1px solid rgba(16,185,129,0.2);\">\n                <div style=\"display:flex; justify-content:space-between; align-items:start;\">\n                    <div>\n                        <div style=\"font-size:16px; font-weight:700;\">{{ active_apk.file_name or 'App.apk' }}</div>\n                        <div style=\"font-size:13px; color:#a78bfa; margin-top:4px;\">\n                            v{{ active_apk.version or 'N/A' }}\n                        </div>\n                    </div>\n                    <span class=\"badge badge-success\">LIVE ✅</span>\n                </div>\n                {% if active_apk.changelog %}\n                <div style=\"margin-top:12px; padding-top:12px; border-top:1px solid var(--border);\">\n                    <div style=\"font-size:11px; color:var(--text3); margin-bottom:6px;\">WHAT'S NEW</div>\n                    <div style=\"font-size:13px; color:var(--text2); white-space:pre-line;\">{{ active_apk.changelog }}</div>\n                </div>\n                {% endif %}\n                <div style=\"margin-top:12px; font-size:11px; color:var(--text3);\">\n                    Added: {{ active_apk.created_at.strftime('%b %d, %Y at %H:%M') if active_apk.created_at else '—' }}\n                </div>\n            </div>\n            <div class=\"mt-3\">\n                <a href=\"/admin/broadcast\" class=\"btn btn-primary btn-sm\">\n                    📢 Broadcast New APK to Users\n                </a>\n            </div>\n            {% else %}\n            <div style=\"text-align:center; padding:40px; color:var(--text3);\">\n                📭 No APK uploaded yet.<br>\n                <span style=\"font-size:12px;\">Upload your first APK using the form on the left.</span>\n            </div>\n            {% endif %}\n        </div>\n\n        <!-- Archived APKs -->\n        {% if archived_apks %}\n        <div class=\"card\">\n            <div class=\"card-header\">📦 Archived APKs</div>\n            <div class=\"table-wrap\">\n                <table>\n                    <thead>\n                        <tr>\n                            <th>File</th>\n                            <th>Version</th>\n                            <th>Archived</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                    {% for apk in archived_apks %}\n                    <tr>\n                        <td>{{ apk.file_name or 'App.apk' }}</td>\n                        <td><span class=\"badge badge-purple\">v{{ apk.version or '—' }}</span></td>\n                        <td style=\"color:var(--text3); font-size:11px;\">\n                            {{ apk.created_at.strftime('%b %d, %Y') if apk.created_at else '—' }}\n                        </td>\n                    </tr>\n                    {% endfor %}\n                    </tbody>\n                </table>\n            </div>\n        </div>\n        {% endif %}\n    </div>\n</div>\n{% endblock %}\n",
    "admin/base.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>{% block title %}NexusBot Admin{% endblock %}</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n    <style>\n        :root {\n            --bg: #0a0a0f;\n            --bg2: #12121a;\n            --bg3: #1a1a27;\n            --card: #16162080;\n            --border: #2a2a3e;\n            --accent: #7c3aed;\n            --accent2: #4f46e5;\n            --accent-glow: rgba(124,58,237,0.3);\n            --success: #10b981;\n            --danger: #ef4444;\n            --warning: #f59e0b;\n            --info: #3b82f6;\n            --text: #e2e8f0;\n            --text2: #94a3b8;\n            --text3: #64748b;\n        }\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body {\n            font-family: 'Inter', sans-serif;\n            background: var(--bg);\n            color: var(--text);\n            min-height: 100vh;\n        }\n        /* Sidebar */\n        .sidebar {\n            position: fixed; top: 0; left: 0; bottom: 0; width: 240px;\n            background: var(--bg2);\n            border-right: 1px solid var(--border);\n            display: flex; flex-direction: column;\n            z-index: 100;\n        }\n        .sidebar-logo {\n            padding: 24px 20px 20px;\n            border-bottom: 1px solid var(--border);\n        }\n        .sidebar-logo h1 {\n            font-size: 20px; font-weight: 800;\n            background: linear-gradient(135deg, #7c3aed, #4f46e5, #06b6d4);\n            -webkit-background-clip: text; -webkit-text-fill-color: transparent;\n        }\n        .sidebar-logo p { font-size: 11px; color: var(--text3); margin-top: 2px; }\n        .sidebar-nav { flex: 1; padding: 16px 12px; overflow-y: auto; }\n        .nav-section { font-size: 10px; font-weight: 600; color: var(--text3);\n            text-transform: uppercase; letter-spacing: 1px; margin: 16px 8px 8px; }\n        .nav-item {\n            display: flex; align-items: center; gap: 10px;\n            padding: 10px 12px; border-radius: 10px;\n            color: var(--text2); text-decoration: none;\n            font-size: 13px; font-weight: 500;\n            transition: all 0.2s; margin-bottom: 2px;\n        }\n        .nav-item:hover { background: var(--bg3); color: var(--text); }\n        .nav-item.active { background: var(--accent-glow); color: #a78bfa;\n            border: 1px solid rgba(124,58,237,0.3); }\n        .nav-item .icon { font-size: 16px; width: 20px; text-align: center; }\n        .sidebar-footer {\n            padding: 16px; border-top: 1px solid var(--border);\n        }\n        .logout-btn {\n            display: flex; align-items: center; gap: 8px;\n            padding: 10px 12px; border-radius: 10px;\n            color: var(--danger); text-decoration: none;\n            font-size: 13px; font-weight: 500; transition: all 0.2s;\n        }\n        .logout-btn:hover { background: rgba(239,68,68,0.1); }\n        /* Main content */\n        .main { margin-left: 240px; min-height: 100vh; }\n        .topbar {\n            padding: 20px 28px; border-bottom: 1px solid var(--border);\n            display: flex; align-items: center; justify-content: space-between;\n            background: var(--bg2);\n            position: sticky; top: 0; z-index: 50;\n        }\n        .topbar h2 { font-size: 18px; font-weight: 700; }\n        .topbar .breadcrumb { font-size: 12px; color: var(--text3); margin-top: 2px; }\n        .content { padding: 28px; }\n        /* Cards */\n        .card {\n            background: var(--bg2); border: 1px solid var(--border);\n            border-radius: 16px; padding: 20px;\n        }\n        .card-header { font-size: 14px; font-weight: 600; color: var(--text2);\n            margin-bottom: 16px; display: flex; align-items: center; gap: 8px; }\n        /* Stat cards */\n        .stats-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px,1fr)); gap: 16px; margin-bottom: 24px; }\n        .stat-card {\n            background: var(--bg2); border: 1px solid var(--border);\n            border-radius: 16px; padding: 20px;\n            position: relative; overflow: hidden;\n            transition: transform 0.2s, border-color 0.2s;\n        }\n        .stat-card:hover { transform: translateY(-2px); border-color: var(--accent); }\n        .stat-card .glow {\n            position: absolute; top: -20px; right: -20px;\n            width: 80px; height: 80px; border-radius: 50%;\n            opacity: 0.15;\n        }\n        .stat-card .label { font-size: 12px; color: var(--text3); font-weight: 500; }\n        .stat-card .value { font-size: 32px; font-weight: 800; margin: 8px 0; }\n        .stat-card .sub { font-size: 11px; color: var(--text3); }\n        /* Alerts */\n        .alert { padding: 12px 16px; border-radius: 10px; margin-bottom: 16px; font-size: 13px; }\n        .alert-success { background: rgba(16,185,129,0.1); border: 1px solid rgba(16,185,129,0.3); color: #6ee7b7; }\n        .alert-danger { background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.3); color: #fca5a5; }\n        .alert-warning { background: rgba(245,158,11,0.1); border: 1px solid rgba(245,158,11,0.3); color: #fcd34d; }\n        .alert-info { background: rgba(59,130,246,0.1); border: 1px solid rgba(59,130,246,0.3); color: #93c5fd; }\n        /* Buttons */\n        .btn {\n            display: inline-flex; align-items: center; gap: 8px;\n            padding: 10px 18px; border-radius: 10px; border: none;\n            font-size: 13px; font-weight: 600; cursor: pointer;\n            text-decoration: none; transition: all 0.2s;\n        }\n        .btn-primary {\n            background: linear-gradient(135deg, var(--accent), var(--accent2));\n            color: white;\n            box-shadow: 0 4px 15px var(--accent-glow);\n        }\n        .btn-primary:hover { transform: translateY(-1px); box-shadow: 0 6px 20px var(--accent-glow); }\n        .btn-success { background: rgba(16,185,129,0.2); color: #6ee7b7; border: 1px solid rgba(16,185,129,0.3); }\n        .btn-success:hover { background: rgba(16,185,129,0.3); }\n        .btn-danger { background: rgba(239,68,68,0.2); color: #fca5a5; border: 1px solid rgba(239,68,68,0.3); }\n        .btn-danger:hover { background: rgba(239,68,68,0.3); }\n        .btn-warning { background: rgba(245,158,11,0.2); color: #fcd34d; border: 1px solid rgba(245,158,11,0.3); }\n        .btn-sm { padding: 6px 12px; font-size: 12px; }\n        .btn-outline {\n            background: transparent; color: var(--text2);\n            border: 1px solid var(--border);\n        }\n        .btn-outline:hover { border-color: var(--accent); color: #a78bfa; }\n        /* Forms */\n        .form-group { margin-bottom: 18px; }\n        .form-label { display: block; font-size: 12px; font-weight: 600; color: var(--text2); margin-bottom: 8px; }\n        .form-control {\n            width: 100%; padding: 10px 14px;\n            background: var(--bg3); border: 1px solid var(--border);\n            border-radius: 10px; color: var(--text);\n            font-size: 13px; font-family: 'Inter', sans-serif;\n            transition: border-color 0.2s;\n        }\n        .form-control:focus { outline: none; border-color: var(--accent); }\n        .form-control textarea { resize: vertical; min-height: 100px; }\n        textarea.form-control { resize: vertical; min-height: 100px; }\n        select.form-control { cursor: pointer; }\n        .form-check { display: flex; align-items: center; gap: 8px; }\n        .form-check input { accent-color: var(--accent); width: 16px; height: 16px; }\n        /* Tables */\n        .table-wrap { overflow-x: auto; border-radius: 12px; border: 1px solid var(--border); }\n        table { width: 100%; border-collapse: collapse; }\n        th { padding: 12px 16px; text-align: left; font-size: 11px; font-weight: 600;\n            color: var(--text3); text-transform: uppercase; letter-spacing: 0.5px;\n            background: var(--bg3); border-bottom: 1px solid var(--border); }\n        td { padding: 12px 16px; font-size: 13px; border-bottom: 1px solid var(--border); }\n        tr:last-child td { border-bottom: none; }\n        tr:hover td { background: var(--bg3); }\n        /* Badges */\n        .badge {\n            display: inline-flex; align-items: center; gap: 4px;\n            padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 600;\n        }\n        .badge-success { background: rgba(16,185,129,0.15); color: #6ee7b7; }\n        .badge-danger { background: rgba(239,68,68,0.15); color: #fca5a5; }\n        .badge-warning { background: rgba(245,158,11,0.15); color: #fcd34d; }\n        .badge-info { background: rgba(59,130,246,0.15); color: #93c5fd; }\n        .badge-purple { background: rgba(124,58,237,0.15); color: #a78bfa; }\n        /* Progress bar */\n        .progress { height: 6px; background: var(--bg3); border-radius: 3px; overflow: hidden; }\n        .progress-bar { height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent2));\n            border-radius: 3px; transition: width 0.5s; }\n        /* Grid helpers */\n        .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }\n        .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }\n        .flex { display: flex; }\n        .flex-between { display: flex; justify-content: space-between; align-items: center; }\n        .gap-2 { gap: 8px; }\n        .gap-3 { gap: 12px; }\n        .mt-3 { margin-top: 12px; }\n        .mt-4 { margin-top: 16px; }\n        .mb-4 { margin-bottom: 16px; }\n        /* Status dot */\n        .status-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }\n        .dot-green { background: #10b981; box-shadow: 0 0 6px #10b981; }\n        .dot-red { background: #ef4444; box-shadow: 0 0 6px #ef4444; }\n        .dot-yellow { background: #f59e0b; box-shadow: 0 0 6px #f59e0b; }\n        .dot-blue { background: #3b82f6; box-shadow: 0 0 6px #3b82f6; }\n    </style>\n    {% block extra_styles %}{% endblock %}\n</head>\n<body>\n<div class=\"sidebar\">\n    <div class=\"sidebar-logo\">\n        <h1>⚡ NexusBot</h1>\n        <p>Admin Control Panel</p>\n    </div>\n    <nav class=\"sidebar-nav\">\n        <div class=\"nav-section\">Overview</div>\n        <a href=\"/admin/dashboard\" class=\"nav-item {% if request.path == '/admin/dashboard' or request.path == '/admin' %}active{% endif %}\">\n            <span class=\"icon\">📊</span> Dashboard\n        </a>\n        <div class=\"nav-section\">Content</div>\n        <a href=\"/admin/content\" class=\"nav-item {% if '/content' in request.path and '/apk' not in request.path %}active{% endif %}\">\n            <span class=\"icon\">📦</span> Content Manager\n        </a>\n        <a href=\"/admin/apk\" class=\"nav-item {% if '/apk' in request.path %}active{% endif %}\">\n            <span class=\"icon\">📱</span> APK Manager\n        </a>\n        <div class=\"nav-section\">Engagement</div>\n        <a href=\"/admin/broadcast\" class=\"nav-item {% if '/broadcast' in request.path %}active{% endif %}\">\n            <span class=\"icon\">📢</span> Broadcast\n        </a>\n        <a href=\"/admin/users\" class=\"nav-item {% if '/users' in request.path %}active{% endif %}\">\n            <span class=\"icon\">👥</span> Users\n        </a>\n        {% if session.get('admin_role') == 'super_admin' %}\n        <div class=\"nav-section\">Admin Management</div>\n        <a href=\"/admin/admins\" class=\"nav-item {% if '/admins' in request.path %}active{% endif %}\">\n            <span class=\"icon\">🔐</span> Manage Admins\n        </a>\n        {% endif %}\n        <div class=\"nav-section\">System</div>\n        <a href=\"/admin/settings\" class=\"nav-item {% if '/settings' in request.path %}active{% endif %}\">\n            <span class=\"icon\">⚙️</span> Settings\n        </a>\n    </nav>\n    <div class=\"sidebar-footer\">\n        <a href=\"/admin/logout\" class=\"logout-btn\">\n            <span>🚪</span> Logout\n        </a>\n    </div>\n</div>\n<div class=\"main\">\n    <div class=\"topbar\">\n        <div>\n            <h2>{% block page_title %}Dashboard{% endblock %}</h2>\n            <div class=\"breadcrumb\">NexusBot › {% block breadcrumb %}Overview{% endblock %}</div>\n        </div>\n        <div class=\"flex gap-3\">\n            {% block topbar_actions %}{% endblock %}\n        </div>\n    </div>\n    <div class=\"content\">\n        {% with messages = get_flashed_messages(with_categories=true) %}\n            {% for category, message in messages %}\n                <div class=\"alert alert-{{ category }}\">{{ message }}</div>\n            {% endfor %}\n        {% endwith %}\n        {% block content %}{% endblock %}\n    </div>\n</div>\n{% block scripts %}{% endblock %}\n</body>\n</html>\n",
    "admin/broadcast.html": "{% extends \"admin/base.html\" %}\n{% block title %}Broadcast — NexusBot Admin{% endblock %}\n{% block page_title %}Broadcast Center{% endblock %}\n{% block breadcrumb %}Broadcast{% endblock %}\n\n{% block topbar_actions %}\n    <span style=\"color:var(--text2); font-size:13px;\">\n        👥 <strong style=\"color:var(--text);\">{{ user_count }}</strong> users will receive this\n    </span>\n{% endblock %}\n\n{% block extra_styles %}\n<style>\n.media-type-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 20px; }\n.type-card {\n    padding: 16px; border-radius: 12px; border: 2px solid var(--border);\n    text-align: center; cursor: pointer; transition: all 0.2s;\n    background: var(--bg3);\n}\n.type-card:hover { border-color: var(--accent); }\n.type-card.selected { border-color: var(--accent); background: var(--accent-glow); }\n.type-card .icon { font-size: 24px; display: block; margin-bottom: 6px; }\n.type-card .name { font-size: 12px; font-weight: 600; color: var(--text2); }\n.section-hidden { display: none; }\n.broadcast-row { display: flex; flex-direction: column; gap: 4px; }\n.progress-wrap { padding: 12px; background: var(--bg3); border-radius: 10px; margin-top: 8px; }\n</style>\n{% endblock %}\n\n{% block content %}\n<div class=\"grid-2\" style=\"gap:24px; align-items:start;\">\n    <!-- Compose Broadcast -->\n    <div class=\"card\">\n        <div class=\"card-header\">📢 Compose Broadcast</div>\n        <form method=\"POST\" action=\"/admin/broadcast/send\" id=\"broadcastForm\">\n            <!-- Message Type Selector -->\n            <div class=\"form-group\">\n                <div class=\"form-label\">MESSAGE TYPE</div>\n                <div class=\"media-type-grid\">\n                    <div class=\"type-card selected\" data-type=\"text\" onclick=\"selectType('text')\">\n                        <span class=\"icon\">📝</span>\n                        <span class=\"name\">Text</span>\n                    </div>\n                    <div class=\"type-card\" data-type=\"voice\" onclick=\"selectType('voice')\">\n                        <span class=\"icon\">🎵</span>\n                        <span class=\"name\">Voice Note</span>\n                    </div>\n                    <div class=\"type-card\" data-type=\"image\" onclick=\"selectType('image')\">\n                        <span class=\"icon\">🖼️</span>\n                        <span class=\"name\">Image</span>\n                    </div>\n                    <div class=\"type-card\" data-type=\"video\" onclick=\"selectType('video')\">\n                        <span class=\"icon\">🎬</span>\n                        <span class=\"name\">Video</span>\n                    </div>\n                    <div class=\"type-card\" data-type=\"audio\" onclick=\"selectType('audio')\">\n                        <span class=\"icon\">🎤</span>\n                        <span class=\"name\">Audio</span>\n                    </div>\n                    <div class=\"type-card\" data-type=\"apk\" onclick=\"selectType('apk')\">\n                        <span class=\"icon\">📱</span>\n                        <span class=\"name\">APK/File</span>\n                    </div>\n                </div>\n                <input type=\"hidden\" name=\"message_type\" id=\"message_type\" value=\"text\">\n            </div>\n\n            <!-- Text message area -->\n            <div class=\"form-group\" id=\"section-text\">\n                <label class=\"form-label\">MESSAGE TEXT (Markdown supported)</label>\n                <textarea name=\"content_text\" class=\"form-control\" rows=\"6\"\n                    placeholder=\"*Bold*, _italic_, `code`&#10;&#10;Write your message here...\"></textarea>\n            </div>\n\n            <!-- File ID for media -->\n            <div class=\"form-group section-hidden\" id=\"section-file\">\n                <label class=\"form-label\">TELEGRAM FILE ID</label>\n                <input type=\"text\" name=\"file_id\" class=\"form-control\"\n                    placeholder=\"Forward the media to your bot and copy the file_id\">\n                <div style=\"margin-top:6px; font-size:11px; color:var(--text3);\">\n                    💡 Forward your media to @userinfobot or check the instructions below to get the file_id\n                </div>\n            </div>\n\n            <!-- Caption for media -->\n            <div class=\"form-group section-hidden\" id=\"section-caption\">\n                <label class=\"form-label\">CAPTION (optional)</label>\n                <textarea name=\"caption\" class=\"form-control\" rows=\"3\"\n                    placeholder=\"Optional caption for the media...\"></textarea>\n            </div>\n\n            <!-- APK Download Button Option -->\n            <div class=\"form-group\" style=\"padding:14px; background:var(--bg3); border-radius:12px; border:1px solid var(--border);\">\n                <div class=\"form-check\">\n                    <input type=\"checkbox\" name=\"has_apk_button\" id=\"has_apk_button\">\n                    <label for=\"has_apk_button\" style=\"font-size:13px; color:var(--text); cursor:pointer;\">\n                        📱 Attach APK Download Button\n                    </label>\n                </div>\n                <div style=\"margin-top:10px;\" id=\"apk-btn-section\" class=\"section-hidden\">\n                    <input type=\"text\" name=\"apk_button_text\" class=\"form-control\"\n                        value=\"⬇️ Download App\"\n                        placeholder=\"Button text\">\n                    {% if active_apk %}\n                    <div style=\"margin-top:6px; font-size:11px; color:#6ee7b7;\">\n                        ✅ Will link to: <strong>{{ active_apk.file_name }}</strong> v{{ active_apk.version }}\n                    </div>\n                    {% else %}\n                    <div style=\"margin-top:6px; font-size:11px; color:#fca5a5;\">\n                        ⚠️ No active APK found. <a href=\"/admin/apk\" style=\"color:#f59e0b;\">Upload one first</a>\n                    </div>\n                    {% endif %}\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <button type=\"submit\" class=\"btn btn-primary\" style=\"width:100%;\"\n                    onclick=\"return confirm('Send to {{ user_count }} users?')\">\n                    🚀 Send Broadcast Now\n                </button>\n            </div>\n        </form>\n    </div>\n\n    <!-- Broadcast History -->\n    <div>\n        <div class=\"card\">\n            <div class=\"card-header\">📊 Broadcast History</div>\n            {% if broadcasts %}\n            <div class=\"table-wrap\">\n                <table>\n                    <thead>\n                        <tr>\n                            <th>#</th>\n                            <th>Type</th>\n                            <th>Progress</th>\n                            <th>Status</th>\n                            <th>Date</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                    {% for b in broadcasts %}\n                    <tr>\n                        <td style=\"color:var(--text3);\">#{{ b.id }}</td>\n                        <td>\n                            {% if b.message_type == 'text' %}📝\n                            {% elif b.message_type == 'image' %}🖼️\n                            {% elif b.message_type == 'video' %}🎬\n                            {% elif b.message_type == 'voice' %}🎵\n                            {% elif b.message_type == 'audio' %}🎤\n                            {% elif b.message_type in ('apk','document') %}📱\n                            {% endif %}\n                            {{ b.message_type | title }}\n                        </td>\n                        <td style=\"min-width:120px;\">\n                            <div class=\"broadcast-row\">\n                                {% set pct = ((b.sent_count / b.total_users * 100) | round(0) | int) if b.total_users else 0 %}\n                                <div class=\"progress\">\n                                    <div class=\"progress-bar\" style=\"width:{{ pct }}%\"></div>\n                                </div>\n                        <span style=\"font-size:11px; color:var(--text3);\">\n                            {{ b.sent_count }}/{{ b.total_users }}\n                            {% if b.failed_count %} · ❌{{ b.failed_count }}{% endif %}\n                        </span>\n                        <span class=\"counter-detail\" style=\"font-size:10px; color:var(--text3); display:block;\"></span>\n                            </div>\n                        </td>\n                        <td>\n                            {% if b.status == 'done' %}<span class=\"badge badge-success\">✅ Done</span>\n                            {% elif b.status == 'sending' %}<span class=\"badge badge-info\" data-broadcast-id=\"{{ b.id }}\">⏳ Sending</span>\n                            {% elif b.status == 'failed' %}<span class=\"badge badge-danger\">❌ Failed</span>\n                            {% else %}<span class=\"badge badge-warning\">🕐 Queued</span>{% endif %}\n                        </td>\n                        <td style=\"color:var(--text3); font-size:11px; white-space:nowrap;\">\n                            {{ b.created_at.strftime('%b %d, %H:%M') if b.created_at else '—' }}\n                        </td>\n                    </tr>\n                    {% endfor %}\n                    </tbody>\n                </table>\n            </div>\n            {% else %}\n            <div style=\"text-align:center; padding:40px; color:var(--text3);\">\n                📭 No broadcasts sent yet\n            </div>\n            {% endif %}\n        </div>\n\n        <div class=\"card mt-4\">\n            <div class=\"card-header\">💡 How to Get File IDs</div>\n            <div style=\"font-size:13px; color:var(--text2); line-height:1.8;\">\n                <p>1. 📤 Send your media (voice/video/image/APK) to your bot in Telegram</p>\n                <p>2. 🤖 Forward that message to <strong>@userinfobot</strong></p>\n                <p>3. 📋 Copy the <strong>file_id</strong> from the response</p>\n                <p>4. 📝 Paste it in the <strong>Telegram File ID</strong> field above</p>\n                <br>\n                <p style=\"color:var(--text3); font-size:11px;\">\n                    Voice notes: Record in Telegram → Send to bot → Forward to @userinfobot\n                </p>\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction selectType(type) {\n    document.querySelectorAll('.type-card').forEach(c => c.classList.remove('selected'));\n    document.querySelector(`[data-type=\"${type}\"]`).classList.add('selected');\n    document.getElementById('message_type').value = type;\n\n    // Show/hide sections\n    document.getElementById('section-text').classList.toggle('section-hidden', type !== 'text');\n    document.getElementById('section-file').classList.toggle('section-hidden', type === 'text');\n    document.getElementById('section-caption').classList.toggle('section-hidden', type === 'text' || type === 'voice');\n}\n\ndocument.getElementById('has_apk_button').addEventListener('change', function() {\n    document.getElementById('apk-btn-section').classList.toggle('section-hidden', !this.checked);\n});\n\n// Live progress polling for sending broadcasts\nfunction pollProgress() {\n    document.querySelectorAll('[data-broadcast-id]').forEach(el => {\n        const id = el.dataset.broadcastId;\n        const row = el.closest('tr');\n        const progressBar = row ? row.querySelector('.progress-bar') : null;\n        const counterSpan = row ? row.querySelector('.counter-detail') : null;\n\n        fetch(`/admin/broadcast/status/${id}`)\n            .then(r => r.json())\n            .then(data => {\n                const pct = data.progress || 0;\n                if (progressBar) progressBar.style.width = pct + '%';\n                if (counterSpan) {\n                    const remaining = Math.max(0, data.total - data.sent - data.failed);\n                    counterSpan.textContent = `${data.sent} sent, ${data.failed} blocked, ${remaining} left`;\n                }\n                if (data.status === 'done' || data.status === 'failed') {\n                    setTimeout(() => location.reload(), 1000);\n                }\n            }).catch(() => {});\n    });\n}\nsetInterval(pollProgress, 2000);\n</script>\n{% endblock %}\n",
    "admin/content.html": "{% extends \"admin/base.html\" %}\n{% block title %}Content Manager — NexusBot Admin{% endblock %}\n{% block page_title %}Content Manager{% endblock %}\n{% block breadcrumb %}Content{% endblock %}\n\n{% block topbar_actions %}\n<a href=\"/admin/content/add\" class=\"btn btn-primary btn-sm\">➕ Add Content</a>\n{% endblock %}\n\n{% block content %}\n<div class=\"card\">\n    <div class=\"card-header\">📦 All Content Items</div>\n    {% if contents %}\n    <div class=\"table-wrap\">\n        <table>\n            <thead>\n                <tr>\n                    <th>Order</th>\n                    <th>Type</th>\n                    <th>Details</th>\n                    <th>Version</th>\n                    <th>Status</th>\n                    <th>Actions</th>\n                </tr>\n            </thead>\n            <tbody>\n            {% for item in contents %}\n            <tr>\n                <td style=\"color:var(--text3);\">{{ item.order_index }}</td>\n                <td>\n                    {% if item.content_type == 'text' %}<span class=\"badge badge-info\">📝 Text</span>\n                    {% elif item.content_type == 'image' %}<span class=\"badge badge-success\">🖼️ Image</span>\n                    {% elif item.content_type == 'video' %}<span class=\"badge badge-purple\">🎬 Video</span>\n                    {% elif item.content_type == 'voice' %}<span class=\"badge badge-warning\">🎵 Voice</span>\n                    {% elif item.content_type == 'audio' %}<span class=\"badge badge-warning\">🎤 Audio</span>\n                    {% elif item.content_type == 'apk' %}<span class=\"badge badge-danger\">📱 APK</span>\n                    {% endif %}\n                </td>\n                <td>\n                    <div style=\"max-width:300px;\">\n                        {% if item.text_content %}\n                        <div style=\"font-size:12px; color:var(--text2); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\">\n                            {{ item.text_content[:80] }}{% if item.text_content|length > 80 %}...{% endif %}\n                        </div>\n                        {% elif item.file_name %}\n                        <div style=\"font-size:13px; font-weight:500;\">{{ item.file_name }}</div>\n                        {% endif %}\n                        {% if item.caption %}\n                        <div style=\"font-size:11px; color:var(--text3); margin-top:2px;\">\n                            {{ item.caption[:60] }}{% if item.caption|length > 60 %}...{% endif %}\n                        </div>\n                        {% endif %}\n                    </div>\n                </td>\n                <td>\n                    {% if item.version %}\n                    <span class=\"badge badge-purple\">v{{ item.version }}</span>\n                    {% else %}—{% endif %}\n                </td>\n                <td>\n                    {% if item.is_active %}\n                    <span class=\"badge badge-success\">Active</span>\n                    {% else %}\n                    <span class=\"badge badge-danger\">Hidden</span>\n                    {% endif %}\n                </td>\n                <td>\n                    <div class=\"flex gap-2\">\n                        <a href=\"/admin/content/edit/{{ item.id }}\" class=\"btn btn-outline btn-sm\">✏️</a>\n                        <form method=\"POST\" action=\"/admin/content/toggle/{{ item.id }}\" style=\"display:inline;\">\n                            <button class=\"btn btn-warning btn-sm\" title=\"Toggle visibility\">\n                                {% if item.is_active %}👁️{% else %}🙈{% endif %}\n                            </button>\n                        </form>\n                        <form method=\"POST\" action=\"/admin/content/delete/{{ item.id }}\" style=\"display:inline;\"\n                            onsubmit=\"return confirm('Delete this content permanently?')\">\n                            <button class=\"btn btn-danger btn-sm\">🗑️</button>\n                        </form>\n                    </div>\n                </td>\n            </tr>\n            {% endfor %}\n            </tbody>\n        </table>\n    </div>\n    {% else %}\n    <div style=\"text-align:center; padding:60px; color:var(--text3);\">\n        📭 No content added yet.<br>\n        <a href=\"/admin/content/add\" style=\"color:#a78bfa; margin-top:8px; display:inline-block;\">\n            ➕ Add your first content item\n        </a>\n    </div>\n    {% endif %}\n</div>\n{% endblock %}\n",
    "admin/content_form.html": "{% extends \"admin/base.html\" %}\n{% block title %}{{ action }} Content — NexusBot Admin{% endblock %}\n{% block page_title %}{{ action }} Content{% endblock %}\n{% block breadcrumb %}Content › {{ action }}{% endblock %}\n\n{% block extra_styles %}\n<style>\n.type-section { display: none; }\n.type-section.active { display: block; }\n</style>\n{% endblock %}\n\n{% block content %}\n<div style=\"max-width:700px;\">\n<div class=\"card\">\n    <div class=\"card-header\">{{ '✏️ Edit' if action == 'Edit' else '➕ Add' }} Content Item</div>\n    <form method=\"POST\">\n        <div class=\"form-group\">\n            <label class=\"form-label\">CONTENT TYPE *</label>\n            <select name=\"content_type\" class=\"form-control\" id=\"typeSelect\" required>\n                <option value=\"\">— Select type —</option>\n                <option value=\"text\" {% if content and content.content_type == 'text' %}selected{% endif %}>📝 Text</option>\n                <option value=\"image\" {% if content and content.content_type == 'image' %}selected{% endif %}>🖼️ Image</option>\n                <option value=\"video\" {% if content and content.content_type == 'video' %}selected{% endif %}>🎬 Video</option>\n                <option value=\"voice\" {% if content and content.content_type == 'voice' %}selected{% endif %}>🎵 Voice Note</option>\n                <option value=\"audio\" {% if content and content.content_type == 'audio' %}selected{% endif %}>🎤 Audio</option>\n                <option value=\"apk\" {% if content and content.content_type == 'apk' %}selected{% endif %}>📱 APK</option>\n            </select>\n        </div>\n\n        <!-- Text fields -->\n        <div class=\"type-section\" id=\"section-text\">\n            <div class=\"form-group\">\n                <label class=\"form-label\">TEXT CONTENT (Markdown)</label>\n                <textarea name=\"text_content\" class=\"form-control\" rows=\"8\"\n                    placeholder=\"*Bold*, _italic_, `code`&#10;&#10;Your content here...\">{{ content.text_content or '' if content else '' }}</textarea>\n            </div>\n        </div>\n\n        <!-- File ID (for all media types) -->\n        <div class=\"type-section\" id=\"section-file\">\n            <div class=\"form-group\">\n                <label class=\"form-label\">TELEGRAM FILE ID *</label>\n                <input type=\"text\" name=\"file_id\" class=\"form-control\"\n                    value=\"{{ content.file_id or '' if content else '' }}\"\n                    placeholder=\"BQACAgIAAxkBAAIB...\">\n                <div style=\"margin-top:6px; font-size:11px; color:var(--text3);\">\n                    Send media to your bot → Forward to @userinfobot → Copy file_id\n                </div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">FILE NAME</label>\n                <input type=\"text\" name=\"file_name\" class=\"form-control\"\n                    value=\"{{ content.file_name or '' if content else '' }}\"\n                    placeholder=\"filename.ext\">\n            </div>\n            <div class=\"type-section\" id=\"section-caption\">\n                <div class=\"form-group\">\n                    <label class=\"form-label\">CAPTION</label>\n                    <textarea name=\"caption\" class=\"form-control\" rows=\"3\"\n                        placeholder=\"Caption shown below the media\">{{ content.caption or '' if content else '' }}</textarea>\n                </div>\n            </div>\n        </div>\n\n        <!-- APK fields -->\n        <div class=\"type-section\" id=\"section-apk\">\n            <div class=\"grid-2\" style=\"gap:12px;\">\n                <div class=\"form-group\">\n                    <label class=\"form-label\">VERSION</label>\n                    <input type=\"text\" name=\"version\" class=\"form-control\"\n                        value=\"{{ content.version or '' if content else '1.0' }}\"\n                        placeholder=\"1.0.0\">\n                </div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">CHANGELOG / WHAT'S NEW</label>\n                <textarea name=\"changelog\" class=\"form-control\" rows=\"4\"\n                    placeholder=\"- Bug fixes&#10;- New features\">{{ content.changelog or '' if content else '' }}</textarea>\n            </div>\n        </div>\n\n        <div class=\"form-group\">\n            <label class=\"form-label\">DISPLAY ORDER</label>\n            <input type=\"number\" name=\"order_index\" class=\"form-control\"\n                value=\"{{ content.order_index if content else 0 }}\" min=\"0\">\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Lower numbers appear first. Content is delivered in order.\n            </div>\n        </div>\n\n        <div style=\"display:flex; gap:12px; margin-top:8px;\">\n            <button type=\"submit\" class=\"btn btn-primary\">\n                {{ '💾 Save Changes' if action == 'Edit' else '✅ Add Content' }}\n            </button>\n            <a href=\"/admin/content\" class=\"btn btn-outline\">Cancel</a>\n        </div>\n    </form>\n</div>\n</div>\n{% endblock %}\n\n{% block scripts %}\n<script>\nconst typeSelect = document.getElementById('typeSelect');\nfunction updateSections() {\n    const type = typeSelect.value;\n    document.querySelectorAll('.type-section').forEach(s => s.classList.remove('active'));\n    if (type === 'text') {\n        document.getElementById('section-text').classList.add('active');\n    } else {\n        document.getElementById('section-file').classList.add('active');\n        if (type !== 'voice') {\n            document.getElementById('section-caption').classList.add('active');\n        }\n        if (type === 'apk') {\n            document.getElementById('section-apk').classList.add('active');\n        }\n    }\n}\ntypeSelect.addEventListener('change', updateSections);\nupdateSections(); // Run on load for edit mode\n</script>\n{% endblock %}\n",
    "admin/dashboard.html": "{% extends \"admin/base.html\" %}\n{% block title %}Dashboard — NexusBot Admin{% endblock %}\n{% block page_title %}Dashboard{% endblock %}\n{% block breadcrumb %}Overview{% endblock %}\n\n{% block topbar_actions %}\n    <form method=\"POST\" action=\"/admin/bot/toggle\" style=\"display:inline;\">\n        {% if bot_enabled %}\n            <button class=\"btn btn-success btn-sm\">\n                <span class=\"status-dot dot-green\"></span> Bot Active\n            </button>\n        {% else %}\n            <button class=\"btn btn-danger btn-sm\">\n                <span class=\"status-dot dot-red\"></span> Bot Offline\n            </button>\n        {% endif %}\n    </form>\n    {% if session.get('admin_role') == 'super_admin' %}\n    <form method=\"POST\" action=\"/admin/webhook/register\" style=\"display:inline;\">\n        <button class=\"btn btn-outline btn-sm\">🔗 Register Webhook</button>\n    </form>\n    {% endif %}\n{% endblock %}\n\n{% block content %}\n<!-- Stats Grid -->\n<div class=\"stats-grid\">\n    <div class=\"stat-card\">\n        <div class=\"glow\" style=\"background: #7c3aed;\"></div>\n        <div class=\"label\">Total Users</div>\n        <div class=\"value\" style=\"color: #a78bfa;\">{{ total_users }}</div>\n        <div class=\"sub\">All registered users</div>\n    </div>\n    <div class=\"stat-card\">\n        <div class=\"glow\" style=\"background: #f59e0b;\"></div>\n        <div class=\"label\">APK Downloads</div>\n        <div class=\"value\" style=\"color: #fcd34d;\">{{ apk_downloads }}</div>\n        <div class=\"sub\">{{ download_rate }}% of users downloaded</div>\n    </div>\n    <div class=\"stat-card\">\n        <div class=\"glow\" style=\"background: #3b82f6;\"></div>\n        <div class=\"label\">Active Content</div>\n        <div class=\"value\" style=\"color: #93c5fd;\">{{ active_content }}</div>\n        <div class=\"sub\">Pieces live</div>\n    </div>\n    <div class=\"stat-card\">\n        <div class=\"glow\" style=\"background: #ef4444;\"></div>\n        <div class=\"label\">Banned Users</div>\n        <div class=\"value\" style=\"color: #fca5a5;\">{{ banned_users }}</div>\n        <div class=\"sub\">Blocked accounts</div>\n    </div>\n</div>\n\n<!-- Bottom Grid -->\n<div class=\"grid-2\" style=\"gap:20px;\">\n    <!-- Recent Broadcasts -->\n    <div class=\"card\">\n        <div class=\"card-header\">📢 Recent Broadcasts</div>\n        {% if recent_broadcasts %}\n        <div class=\"table-wrap\">\n            <table>\n                <thead>\n                    <tr>\n                        <th>#</th>\n                        <th>Type</th>\n                        <th>Sent</th>\n                        <th>Status</th>\n                    </tr>\n                </thead>\n                <tbody>\n                {% for b in recent_broadcasts %}\n                <tr>\n                    <td style=\"color: var(--text3);\">#{{ b.id }}</td>\n                    <td>\n                        {% if b.message_type == 'text' %}📝\n                        {% elif b.message_type == 'image' %}🖼️\n                        {% elif b.message_type == 'video' %}🎬\n                        {% elif b.message_type == 'voice' %}🎵\n                        {% elif b.message_type == 'audio' %}🎤\n                        {% elif b.message_type in ('apk','document') %}📱\n                        {% endif %}\n                        {{ b.message_type | title }}\n                    </td>\n                    <td>{{ b.sent_count }}/{{ b.total_users }}</td>\n                    <td>\n                        {% if b.status == 'done' %}<span class=\"badge badge-success\">✅ Done</span>\n                        {% elif b.status == 'sending' %}<span class=\"badge badge-info\">⏳ Sending</span>\n                        {% elif b.status == 'failed' %}<span class=\"badge badge-danger\">❌ Failed</span>\n                        {% else %}<span class=\"badge badge-warning\">🕐 Pending</span>{% endif %}\n                    </td>\n                </tr>\n                {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        {% else %}\n        <div style=\"text-align:center; padding:30px; color:var(--text3);\">\n            No broadcasts yet. <a href=\"/admin/broadcast\" style=\"color:#a78bfa;\">Send your first one!</a>\n        </div>\n        {% endif %}\n        <div class=\"mt-3\">\n            <a href=\"/admin/broadcast\" class=\"btn btn-primary btn-sm\">📢 New Broadcast</a>\n        </div>\n    </div>\n\n    <!-- Active APK + Quick Actions -->\n    <div style=\"display:flex; flex-direction:column; gap:16px;\">\n        <div class=\"card\">\n            <div class=\"card-header\">📱 Active APK</div>\n            {% if active_apk %}\n            <div style=\"padding:12px; background:var(--bg3); border-radius:10px; margin-bottom:12px;\">\n                <div style=\"font-weight:700; font-size:15px;\">{{ active_apk.file_name or 'App.apk' }}</div>\n                <div style=\"color:var(--text3); font-size:12px; margin-top:4px;\">\n                    Version: <strong style=\"color:#a78bfa;\">{{ active_apk.version or 'N/A' }}</strong>\n                </div>\n                {% if active_apk.changelog %}\n                <div style=\"color:var(--text2); font-size:12px; margin-top:8px;\">{{ active_apk.changelog }}</div>\n                {% endif %}\n            </div>\n            <span class=\"badge badge-success\">✅ Live</span>\n            {% else %}\n            <div style=\"color:var(--text3); font-size:13px; margin-bottom:12px;\">No APK uploaded yet.</div>\n            {% endif %}\n            <div class=\"mt-3\">\n                <a href=\"/admin/apk\" class=\"btn btn-primary btn-sm\">📱 Manage APK</a>\n            </div>\n        </div>\n\n        <div class=\"card\">\n            <div class=\"card-header\">⚡ Quick Actions</div>\n            <div style=\"display:flex; flex-direction:column; gap:8px;\">\n                <a href=\"/admin/content/add\" class=\"btn btn-outline\">➕ Add Content</a>\n                <a href=\"/admin/broadcast\" class=\"btn btn-primary\">📢 Send Broadcast</a>\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n\n{% block scripts %}\n<script>\n// Auto-refresh broadcast statuses\nsetInterval(() => {\n    document.querySelectorAll('[data-broadcast-id]').forEach(el => {\n        const id = el.dataset.broadcastId;\n        fetch(`/admin/broadcast/status/${id}`)\n            .then(r => r.json())\n            .then(data => {\n                if (data.status === 'done' || data.status === 'failed') {\n                    location.reload();\n                }\n            });\n    });\n}, 5000);\n</script>\n{% endblock %}\n",
    "admin/login.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>NexusBot Admin — Login</title>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n    <style>\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body {\n            font-family: 'Inter', sans-serif;\n            background: #0a0a0f;\n            min-height: 100vh;\n            display: flex; align-items: center; justify-content: center;\n            position: relative; overflow: hidden;\n        }\n        body::before {\n            content: '';\n            position: absolute; inset: 0;\n            background:\n                radial-gradient(ellipse at 20% 50%, rgba(124,58,237,0.15) 0%, transparent 60%),\n                radial-gradient(ellipse at 80% 20%, rgba(79,70,229,0.1) 0%, transparent 60%),\n                radial-gradient(ellipse at 60% 80%, rgba(6,182,212,0.08) 0%, transparent 60%);\n        }\n        .login-box {\n            background: rgba(22,22,32,0.8);\n            border: 1px solid rgba(42,42,62,0.8);\n            backdrop-filter: blur(20px);\n            border-radius: 24px;\n            padding: 48px 40px;\n            width: 100%; max-width: 420px;\n            position: relative; z-index: 1;\n            box-shadow: 0 25px 50px rgba(0,0,0,0.5);\n        }\n        .logo {\n            text-align: center; margin-bottom: 36px;\n        }\n        .logo h1 {\n            font-size: 32px; font-weight: 800;\n            background: linear-gradient(135deg, #7c3aed, #4f46e5, #06b6d4);\n            -webkit-background-clip: text; -webkit-text-fill-color: transparent;\n        }\n        .logo p { color: #64748b; font-size: 14px; margin-top: 6px; }\n        .form-group { margin-bottom: 20px; }\n        label {\n            display: block; font-size: 12px; font-weight: 600;\n            color: #94a3b8; margin-bottom: 8px; letter-spacing: 0.5px;\n        }\n        input {\n            width: 100%; padding: 14px 16px;\n            background: rgba(26,26,39,0.8); border: 1px solid #2a2a3e;\n            border-radius: 12px; color: #e2e8f0;\n            font-size: 14px; font-family: 'Inter', sans-serif;\n            transition: border-color 0.2s, box-shadow 0.2s;\n        }\n        input:focus {\n            outline: none; border-color: #7c3aed;\n            box-shadow: 0 0 0 3px rgba(124,58,237,0.15);\n        }\n        .btn-login {\n            width: 100%; padding: 14px;\n            background: linear-gradient(135deg, #7c3aed, #4f46e5);\n            border: none; border-radius: 12px;\n            color: white; font-size: 15px; font-weight: 700;\n            cursor: pointer; transition: all 0.2s;\n            box-shadow: 0 8px 25px rgba(124,58,237,0.4);\n            margin-top: 8px;\n        }\n        .btn-login:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 12px 30px rgba(124,58,237,0.5);\n        }\n        .btn-login:active { transform: translateY(0); }\n        .alert {\n            padding: 12px 16px; border-radius: 10px; margin-bottom: 20px;\n            font-size: 13px; background: rgba(239,68,68,0.1);\n            border: 1px solid rgba(239,68,68,0.3); color: #fca5a5;\n        }\n        .lock-icon {\n            text-align: center; font-size: 48px; margin-bottom: 16px;\n        }\n        .footer-note {\n            text-align: center; margin-top: 24px;\n            font-size: 11px; color: #475569;\n        }\n    </style>\n</head>\n<body>\n<div class=\"login-box\">\n    <div class=\"logo\">\n        <div class=\"lock-icon\">🔐</div>\n        <h1>⚡ NexusBot</h1>\n        <p>Admin Control Panel — Authorized Access Only</p>\n    </div>\n    {% with messages = get_flashed_messages(with_categories=true) %}\n        {% for category, message in messages %}\n            <div class=\"alert\">{{ message }}</div>\n        {% endfor %}\n    {% endwith %}\n    <form method=\"POST\">\n        <div class=\"form-group\">\n            <label>USERNAME</label>\n            <input type=\"text\" name=\"username\" placeholder=\"Enter admin username\" autofocus required>\n        </div>\n        <div class=\"form-group\">\n            <label>PASSWORD</label>\n            <input type=\"password\" name=\"password\" placeholder=\"Enter admin password\" required>\n        </div>\n        <button type=\"submit\" class=\"btn-login\">🚀 Access Panel</button>\n    </form>\n    <div class=\"footer-note\">NexusBot Admin v1.0 — Unauthorized access is prohibited</div>\n</div>\n</body>\n</html>\n",
    "admin/settings.html": "{% extends \"admin/base.html\" %}\n{% block title %}Settings — NexusBot Admin{% endblock %}\n{% block page_title %}Bot Settings{% endblock %}\n{% block breadcrumb %}Settings{% endblock %}\n\n{% block content %}\n<div style=\"max-width:700px;\">\n<div class=\"card\">\n    <div class=\"card-header\">⚙️ Bot Configuration</div>\n    <form method=\"POST\">\n        <div class=\"form-group\">\n            <label class=\"form-label\">WELCOME MESSAGE</label>\n            <textarea name=\"welcome_text\" class=\"form-control\" rows=\"5\">{{ configs.welcome_text }}</textarea>\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Supports Markdown: *bold*, _italic_, `code`\n            </div>\n        </div>\n        <div class=\"form-group\">\n            <label class=\"form-label\">WELCOME GIF / STICKER FILE ID (optional)</label>\n            <input type=\"text\" name=\"welcome_gif_id\" class=\"form-control\"\n                value=\"{{ configs.welcome_gif_id }}\"\n                placeholder=\"Telegram file_id for an animation/sticker\">\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Leave blank to show text-only welcome. Send a GIF to your bot → @userinfobot → copy file_id\n            </div>\n        </div>\n        <div class=\"form-group\">\n            <label class=\"form-label\">MAINTENANCE MESSAGE</label>\n            <textarea name=\"maintenance_message\" class=\"form-control\" rows=\"3\">{{ configs.maintenance_message }}</textarea>\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Shown to users when bot is in maintenance mode (toggle from Dashboard)\n            </div>\n        </div>\n        <div class=\"form-group\">\n            <label class=\"form-label\">APK DOWNLOAD BUTTON TEXT</label>\n            <input type=\"text\" name=\"apk_button_text\" class=\"form-control\"\n                value=\"{{ configs.apk_button_text }}\"\n                placeholder=\"⬇️ Download App\">\n        </div>\n        <div class=\"form-group\">\n            <label class=\"form-label\">DEMO CLOSING MESSAGE (shown after content)</label>\n            <textarea name=\"demo_closing_text\" class=\"form-control\" rows=\"4\">{{ configs.demo_closing_text }}</textarea>\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Use <code>{name}</code> to insert user's name. Supports Markdown.\n            </div>\n        </div>\n        <div class=\"form-group\">\n            <label class=\"form-label\">APK INSTALL GUIDE TEXT</label>\n            <textarea name=\"install_guide_text\" class=\"form-control\" rows=\"4\">{{ configs.install_guide_text }}</textarea>\n            <div style=\"font-size:11px; color:var(--text3); margin-top:4px;\">\n                Step-by-step instructions shown after APK download.\n            </div>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary\">💾 Save All Settings</button>\n    </form>\n</div>\n</div>\n{% endblock %}\n",
    "admin/users.html": "{% extends \"admin/base.html\" %}\n{% block title %}Users — NexusBot Admin{% endblock %}\n{% block page_title %}User Manager{% endblock %}\n{% block breadcrumb %}Users{% endblock %}\n\n{% block content %}\n<div class=\"card\">\n    <div class=\"flex-between mb-4\">\n        <div class=\"card-header\" style=\"margin:0;\">👥 Users ({{ total }})</div>\n        <form method=\"GET\" style=\"display:flex; gap:8px;\">\n            <input type=\"text\" name=\"search\" class=\"form-control\" value=\"{{ search }}\"\n                placeholder=\"Search username or name...\" style=\"width:260px;\">\n            <button type=\"submit\" class=\"btn btn-outline btn-sm\">🔍 Search</button>\n            {% if search %}<a href=\"/admin/users\" class=\"btn btn-outline btn-sm\">✕ Clear</a>{% endif %}\n        </form>\n    </div>\n    {% if users %}\n    <div class=\"table-wrap\">\n        <table>\n            <thead>\n                <tr>\n                    <th>User</th>\n                    <th>Streak</th>\n                    <th>APK Downloaded</th>\n                    <th>Joined</th>\n                    <th>Status</th>\n                    <th>Actions</th>\n                </tr>\n            </thead>\n            <tbody>\n            {% for u in users %}\n            <tr>\n                <td>\n                    <div>\n                        <div style=\"font-weight:600; font-size:13px;\">{{ u.first_name or '—' }} {{ u.last_name or '' }}</div>\n                        <div style=\"color:var(--text3); font-size:11px;\">\n                            {% if u.username %}@{{ u.username }}{% endif %}\n                            · {{ u.id }}\n                        </div>\n                    </div>\n                </td>\n                <td>\n                    <span class=\"badge badge-warning\">🔥 {{ u.streak_count }}d</span>\n                </td>\n                <td>\n                    {% if u.downloaded_apk %}<span class=\"badge badge-success\">✅ Downloaded</span>{% else %}<span class=\"badge badge-warning\">⏳ Not Yet</span>{% endif %}\n                </td>\n                <td style=\"color:var(--text3); font-size:11px; white-space:nowrap;\">\n                    {{ u.joined_at.strftime('%b %d, %Y') if u.joined_at else '—' }}\n                </td>\n                <td>\n                    {% if u.is_banned %}\n                    <span class=\"badge badge-danger\">🚫 Banned</span>\n                    {% else %}\n                    <span class=\"badge badge-success\">✅ Active</span>\n                    {% endif %}\n                </td>\n                <td>\n                    <form method=\"POST\" action=\"/admin/users/ban/{{ u.id }}\" style=\"display:inline;\">\n                        <button class=\"btn btn-sm {{ 'btn-success' if u.is_banned else 'btn-danger' }}\">\n                            {{ '✅ Unban' if u.is_banned else '🚫 Ban' }}\n                        </button>\n                    </form>\n                </td>\n            </tr>\n            {% endfor %}\n            </tbody>\n        </table>\n    </div>\n    <!-- Pagination -->\n    {% if pages > 1 %}\n    <div style=\"display:flex; gap:8px; margin-top:16px; justify-content:center;\">\n        {% for p in range(1, pages+1) %}\n        <a href=\"/admin/users?page={{ p }}{% if search %}&search={{ search }}{% endif %}\"\n            class=\"btn btn-sm {{ 'btn-primary' if p == page else 'btn-outline' }}\">\n            {{ p }}\n        </a>\n        {% endfor %}\n    </div>\n    {% endif %}\n    {% else %}\n    <div style=\"text-align:center; padding:60px; color:var(--text3);\">\n        👤 No users found{% if search %} for \"{{ search }}\"{% endif %}\n    </div>\n    {% endif %}\n</div>\n{% endblock %}\n",
}
